// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { expandQuery, expansionSkipsAllLoaded } from "../../../main/frontend/graph-explorer/rdf-vocabulary.ts";

/** The Workbench's Graph page accepts queries up to this many characters (graph-max-query-length). */
const SERVLET_LIMIT = 150000;

test("expanding many expanded nodes stays within the query length the Graph page accepts", () => {
  const ids = Array.from({ length: 40 }, (_, index) => `http://example.org/a-rather-long-namespace/resource-${index}`);
  const loaded = new Map(
    ids.map((id) => [
      id,
      {
        outgoing: Array.from({ length: 1000 }, (_, index) => ["<http://example.org/vocabulary/linksTo>", `<${id}/target-${index}>`]),
        incoming: Array.from({ length: 1000 }, (_, index) => [`<${id}/source-${index}>`, "<http://example.org/vocabulary/linksTo>"]),
      },
    ]),
  );
  const query = expandQuery(ids, 12, "default", true, loaded);
  assert.ok(query.length < SERVLET_LIMIT, `${query.length} characters`);
  assert.match(query, /MINUS \{ VALUES/, "loaded statements are still left out");
});

test("very long values are not written into the query; a node's other loaded statements still are", () => {
  const long = `"${"x".repeat(5000)}"`;
  const query = expandQuery(["urn:a"], 80, "default", false, new Map([["urn:a", { outgoing: [["<urn:p>", long], ["<urn:p>", "<urn:b>"]], incoming: [] }]]));
  assert.ok(!query.includes("xxxxxxxxxx"));
  assert.match(query, /\(<urn:p> <urn:b>\)/);
});

// When the loaded statements do not all fit into the query, some come back: Expand must not take an answer made only
// of loaded statements for "no more links", and pages past them instead.
test("Expand knows whether every loaded statement was left out", () => {
  const few = new Map([["urn:a", { outgoing: [["<urn:p>", "<urn:b>"]], incoming: [["<urn:c>", "<urn:p>"]] }]]);
  assert.equal(expansionSkipsAllLoaded(["urn:a"], few), true);
  assert.equal(expansionSkipsAllLoaded(["urn:a"], undefined), true);
  const ids = Array.from({ length: 40 }, (_, index) => `http://example.org/a-rather-long-namespace/resource-${index}`);
  const many = new Map(ids.map((id) => [id, {
    outgoing: Array.from({ length: 1000 }, (_, index) => ["<http://example.org/vocabulary/linksTo>", `<${id}/target-${index}>`]),
    incoming: [],
  }]));
  assert.equal(expansionSkipsAllLoaded(ids, many), false, "past the budget");
  const long = new Map([["urn:a", { outgoing: [["<urn:p>", `"${"x".repeat(5000)}"`]], incoming: [] }]]);
  assert.equal(expansionSkipsAllLoaded(["urn:a"], long), false, "a value too long to write out comes back");
  const blanks = new Map([["urn:a", { outgoing: [], incoming: [], blankOutgoing: ["<urn:p>"] }]]);
  assert.equal(expansionSkipsAllLoaded(["urn:a"], blanks), true);
});

test("Expand pages past what came back with an offset per node and direction", () => {
  const paged = expandQuery(["urn:a", "urn:b"], 12, "default", true, undefined, 24);
  assert.equal(paged.match(/LIMIT 12 OFFSET 24/g).length, 4);
  assert.doesNotMatch(expandQuery(["urn:a"], 12, "default"), /OFFSET/);
});
